BEGIN;
CREATE TABLE IF NOT EXISTS jdatna.roles (name text PRIMARY KEY CHECK(name IN ('customer','producer','admin')));
INSERT INTO jdatna.roles VALUES ('customer'),('producer'),('admin') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS jdatna.users (id uuid PRIMARY KEY, phone text UNIQUE NOT NULL, name text NOT NULL, role text NOT NULL DEFAULT 'customer' REFERENCES jdatna.roles(name), phone_verified_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jdatna.sessions (token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES jdatna.users(id),expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON jdatna.sessions(expires_at);
CREATE TABLE IF NOT EXISTS jdatna.otp_challenges (id uuid PRIMARY KEY,phone text NOT NULL,code_hash text NOT NULL,attempts integer NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE TABLE IF NOT EXISTS jdatna.rate_limits (key text PRIMARY KEY, count integer NOT NULL,reset_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS jdatna.regions (id text PRIMARY KEY,name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS jdatna.cities (id text PRIMARY KEY,name text NOT NULL,region_id text NOT NULL REFERENCES jdatna.regions(id),UNIQUE(region_id,name));
CREATE TABLE IF NOT EXISTS jdatna.neighborhoods (id uuid PRIMARY KEY,name text NOT NULL,city_id text NOT NULL REFERENCES jdatna.cities(id),UNIQUE(city_id,name));
CREATE TABLE IF NOT EXISTS jdatna.categories (id text PRIMARY KEY,name text NOT NULL,slug text UNIQUE NOT NULL,icon text NOT NULL DEFAULT '✦');
CREATE TABLE IF NOT EXISTS jdatna.producer_profiles (id uuid PRIMARY KEY,user_id uuid UNIQUE NOT NULL REFERENCES jdatna.users(id),slug text UNIQUE NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',city_id text NOT NULL REFERENCES jdatna.cities(id),neighborhood text,phone text NOT NULL,whatsapp text,delivery boolean NOT NULL DEFAULT false,pickup boolean NOT NULL DEFAULT true,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','suspended')),verified boolean NOT NULL DEFAULT false,logo_url text,cover_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jdatna.producer_documents (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES jdatna.users(id),type text NOT NULL,object_key text UNIQUE NOT NULL,mime text NOT NULL,size integer NOT NULL CHECK(size BETWEEN 1 AND 10485760),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jdatna.producer_verifications (id uuid PRIMARY KEY,producer_id uuid NOT NULL REFERENCES jdatna.producer_profiles(id),document_id uuid REFERENCES jdatna.producer_documents(id),document_type text NOT NULL,decision text NOT NULL DEFAULT 'pending',reason text,reviewer_id uuid REFERENCES jdatna.users(id),eligibility_confirmed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jdatna.producer_categories (producer_id uuid REFERENCES jdatna.producer_profiles(id),category_id text REFERENCES jdatna.categories(id),PRIMARY KEY(producer_id,category_id));
CREATE TABLE IF NOT EXISTS jdatna.producer_social_links (producer_id uuid REFERENCES jdatna.producer_profiles(id),platform text NOT NULL,url text NOT NULL CHECK(url LIKE 'https://%'),PRIMARY KEY(producer_id,platform));
CREATE TABLE IF NOT EXISTS jdatna.business_hours (producer_id uuid REFERENCES jdatna.producer_profiles(id),day smallint CHECK(day BETWEEN 0 AND 6),opens time,closes time,PRIMARY KEY(producer_id,day));
CREATE TABLE IF NOT EXISTS jdatna.delivery_areas (producer_id uuid REFERENCES jdatna.producer_profiles(id),city_id text REFERENCES jdatna.cities(id),fee numeric(10,2) CHECK(fee>=0),PRIMARY KEY(producer_id,city_id));
CREATE TABLE IF NOT EXISTS jdatna.pickup_locations (id uuid PRIMARY KEY,producer_id uuid NOT NULL REFERENCES jdatna.producer_profiles(id),private_address text,latitude numeric,longitude numeric);
CREATE TABLE IF NOT EXISTS jdatna.products (id uuid PRIMARY KEY,producer_id uuid NOT NULL REFERENCES jdatna.producer_profiles(id),name text NOT NULL,description text NOT NULL,price numeric(10,2) CHECK(price>=0),unit text NOT NULL,status text NOT NULL CHECK(status IN ('available','unavailable','preorder')),visible boolean NOT NULL DEFAULT true,image_url text,ingredients text,storage text,shelf_life text,preparation_time text,story text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_producer_idx ON jdatna.products(producer_id);
CREATE TABLE IF NOT EXISTS jdatna.product_categories (product_id uuid REFERENCES jdatna.products(id),category_id text REFERENCES jdatna.categories(id),PRIMARY KEY(product_id,category_id));
CREATE TABLE IF NOT EXISTS jdatna.product_allergens (product_id uuid REFERENCES jdatna.products(id),name text NOT NULL,PRIMARY KEY(product_id,name));
CREATE TABLE IF NOT EXISTS jdatna.product_media (id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES jdatna.products(id),url text NOT NULL,kind text NOT NULL CHECK(kind IN ('image','video')));
CREATE TABLE IF NOT EXISTS jdatna.reports (id uuid PRIMARY KEY,reporter_id uuid REFERENCES jdatna.users(id),product_id uuid REFERENCES jdatna.products(id),producer_id uuid REFERENCES jdatna.producer_profiles(id),reason text NOT NULL,status text NOT NULL DEFAULT 'new',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jdatna.admin_audit_logs (id uuid PRIMARY KEY,actor_id uuid NOT NULL REFERENCES jdatna.users(id),action text NOT NULL,target_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jdatna.platform_settings (key text PRIMARY KEY,value jsonb NOT NULL);
COMMIT;
